  event_type: "view" | "cart" | "purchase";
  properties: {
    price?: number;
    page?: string;
  };
}

// Ingest pipeline for product events
export const ProductEventPipeline = new IngestPipeline<ProductEvent>("ProductEvent", {
  table: {
    orderByFields: ["event_ts", "user_id", "product_id"]
  },
  stream: true,
  ingestApi: true,
});

// Top products aggregation view
export interface TopProducts {
  product_id: string;
  view_count: number;
  cart_count: number;
  purchase_count: number;
  total_revenue: number;
  last_updated: Date;
}

// Conversion funnel aggregation view
export interface ConversionFunnel {
  unique_viewers: number;
  unique_carters: number;
  unique_purchasers: number;
  total_views: number;
  total_carts: number;
  total_purchases: number;
  last_updated: Date;
}

// Hourly activity aggregation view
export interface HourlyActivity {
  hour: Date;
  event_type: string;
  event_count: number;
  last_updated: Date;
}

// Create aggregation tables
export const TopProductsPipeline = new IngestPipeline<TopProducts>("TopProducts", {
  table: {
    orderByFields: ["product_id"]
  },
  stream: false,
  ingestApi: false,
});

export const ConversionFunnelPipeline = new IngestPipeline<ConversionFunnel>("ConversionFunnel", {
  table: {
    orderByFields: ["last_updated"]
  },
  stream: false,
  ingestApi: false,
});

