  name: "top-products",
  table: "TopProducts",
  routeMethod: "get",
  sql: `
    SELECT
      product_id,
      view_count,
      cart_count,
      purchase_count,
      total_revenue,
      last_updated
    FROM TopProducts
    ORDER BY total_revenue DESC, purchase_count DESC
  `
});

export const ConversionFunnelAPI = new ConsumptionApi({
  name: "conversion-funnel",
  table: "ConversionFunnel",
  routeMethod: "get",
  sql: `
    SELECT
      unique_viewers,
      unique_carters,
      unique_purchasers,
      total_views,
      total_carts,
      total_purchases,
      last_updated
    FROM ConversionFunnel
    ORDER BY last_updated DESC
    LIMIT 1
  `
});

export const HourlyActivityAPI = new ConsumptionApi({
  name: "hourly-activity",
  table: "HourlyActivity",
  routeMethod: "get",
  sql: `
    SELECT
      hour,
      event_type,
      event_count,
      last_updated
    FROM HourlyActivity
    ORDER BY hour DESC, event_type
  `
});

